mapper.insert:
INSERT INTO combined_performance_ranking ( stat_month, principal_name, gross_profit, net_sales_amount, create_time, update_time ) SELECT source.stat_month, source.principal_name, SUM(source.gross_profit) AS gross_profit, SUM(source.net_sales_amount) AS net_sales_amount, NOW(), NOW() FROM ( SELECT stat_month, principal_name, COALESCE(gross_profit, 0) AS gross_profit, COALESCE(net_sales_amount, 0) AS net_sales_amount FROM amz_performance_ranking WHERE stat_month = #{statMonth}
UNION ALL
SELECT stat_month, principal_name, COALESCE(gross_profit, 0) AS gross_profit, COALESCE(net_sales_amount, 0) AS net_sales_amount FROM ebay_performance_ranking WHERE stat_month = #{statMonth} ) source GROUP BY source.stat_month, source.principal_name
